  "resume_en": "After yet another humiliating defeat of the Japanese national team in the World Cup, the Japanese Football Federation hires Jinpachi Ego, a coach with radical methods. His theory: Japan has never produced a world-class striker because its culture values teamwork too much. He creates Blue Lock, a program locking 300 young strikers in a high-tech prison where only the most selfish will survive. Yoichi Isagi, a high schooler who missed a decisive opportunity by passing instead of shooting, sees this as his chance to be reborn. In this hell where elimination is permanent, he must become the most selfish striker in the world or abandon his football dreams forever.",
