  "resume_en": "Two 20-year-old young women, both named Nana, meet on a train to Tokyo and end up as roommates. Nana Komatsu, nicknamed 'Hachi', is a romantic and dependent girl who came to Tokyo to join her boyfriend. Nana Osaki is a determined punk-rocker, singer of the band Blast, who came to conquer the music scene. Their opposite personalities create an intense friendship. But love complicates everything: Hachi flits between several men, while Nana reconnects with her ex Ren, who became guitarist of the rival band Trapnest. Success, jealousy, unwanted pregnancies, and addictions will put their friendship to the test.",
