  "id": 79,
  "titre": "Edens Zero",
  "auteur": "Hiro Mashima",
  "genre": ["Shonen", "Science-fiction", "Action", "Aventure"],
  "annee": 2018,
  "statut": "Terminé",
  "volumes": 33,
  "couverture": "images/covers/79.webp",
  "resume": "Shiki Granbell a grandi seul sur la planète Granbell, entouré uniquement de robots dans un parc d'attractions abandonné. Quand Rebecca, une vidéaste B-Cuber, et son chat bleu Happy arrivent sur la planète, Shiki découvre l'amitié humaine pour la première fois. Mais les robots se rebellent pour forcer Shiki à partir et vivre parmi les humains avant qu'ils ne s'éteignent définitivement. Shiki, Rebecca et Happy embarquent à bord du vaisseau Edens Zero pour explorer le cosmos Sakura et trouver Mother, une déesse cosmique légendaire. Shiki possède l'Ether Gear Gravity, lui permettant de contrôler la gravité.",
  "resume_en": "Shiki Granbell grew up alone on planet Granbell, surrounded only by robots in an abandoned amusement park. When Rebecca, a B-Cuber video creator, and her blue cat Happy arrive on the planet, Shiki discovers human friendship for the first time. But the robots rebel to force Shiki to leave and live among humans before they shut down permanently. Shiki, Rebecca, and Happy board the Edens Zero ship to explore the Sakura Cosmos and find Mother, a legendary cosmic goddess. Shiki possesses the Ether Gear Gravity, allowing him to control gravity.",
