  "auteur": "Yoshifumi Tozuka",
  "genre": ["Shonen", "Action", "Surnaturel", "Comédie"],
  "annee": 2020,
  "statut": "En cours",
  "volumes": 20,
  "couverture": "images/covers/108.webp",
  "resume": "Fuuko Izumo possède le pouvoir Unluck : elle cause la malchance à quiconque la touche. Après avoir provoqué la mort de ses parents, elle décide de se suicider. Mais elle rencontre Andy, un homme immortel (Undead) qui cherche à mourir pour de bon. Ils réalisent que sa malchance pourrait enfin le tuer. Rejoignant l'Union, organisation secrète de Negators (possesseurs de pouvoirs niant des concepts), ils affrontent les UMA, créatures apocalyptiques, et Dieu lui-même qui impose des règles absurdes à l'univers. Un manga déjanté où les pouvoirs défient la logique.",
  "resume_en": "Fuuko Izumo possesses the power Unluck: she causes misfortune to anyone who touches her. After causing her parents' death, she decides to commit suicide. But she meets Andy, an immortal man (Undead) seeking to die for good. They realize her bad luck could finally kill him. Joining the Union, a secret organization of Negators (possessors of concept-negating powers), they face UMAs, apocalyptic creatures, and God himself who imposes absurd rules on the universe. A wild manga where powers defy logic.",
